import { readFileSync, readdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import {
  applyAction,
  placementEligibility,
  worldFrom,
  type GameModel,
  type Value,
} from './interpreter.ts';

interface Case {
  id: string;
  rule: string;
  description: string;
  given: {
    state: string;
    prevState?: string;
    now?: number;
    persona?: { skill?: number; churnSensitivity?: number };
    vars: Record<string, Value>;
  };
  when: { action: string; outcome?: string } | { placement: string };
  then: unknown;
}

/** What the system under test does for a case. Swap this for your backend adapter. */
export function run(model: GameModel, c: Case): unknown {
  const w = worldFrom(model, c.given);
  if ('placement' in c.when) return placementEligibility(model, w, c.when.placement);
  const r = applyAction(model, w, c.when.action, c.when.outcome);
  return {
    result: r.result,
    error: r.error,
    outcome: r.outcome,
    deltas: r.deltas,
    impressions: r.impressions,
  };
}

function canonical(v: unknown): string {
  if (Array.isArray(v)) return `[${v.map(canonical).join(',')}]`;
  if (v !== null && typeof v === 'object') {
    return `{${Object.keys(v)
      .filter((k) => (v as Record<string, unknown>)[k] !== undefined)
      .sort()
      .map((k) => `${JSON.stringify(k)}:${canonical((v as Record<string, unknown>)[k])}`)
      .join(',')}}`;
  }
  return JSON.stringify(v);
}

const packDir = process.argv[2] ?? join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const model = JSON.parse(readFileSync(join(packDir, 'game-model.json'), 'utf8')) as GameModel;
const goldenDir = join(packDir, 'tests', 'golden');
const cases = readdirSync(goldenDir)
  .filter((f) => f.endsWith('.json'))
  .sort()
  .flatMap(
    (f) => (JSON.parse(readFileSync(join(goldenDir, f), 'utf8')) as { cases: Case[] }).cases,
  );

let failed = 0;
console.log('TAP version 13');
console.log(`1..${String(cases.length)}`);
cases.forEach((c, i) => {
  let actual: unknown;
  try {
    actual = run(model, c);
  } catch (error) {
    actual = { error: String(error) };
  }
  const ok = canonical(actual) === canonical(c.then);
  if (!ok) failed++;
  console.log(`${ok ? 'ok' : 'not ok'} ${String(i + 1)} - ${c.id}: ${c.description}`);
  if (!ok) {
    console.log('  ---');
    console.log(`  rule: ${c.rule}`);
    console.log(`  expected: ${canonical(c.then)}`);
    console.log(`  actual:   ${canonical(actual)}`);
    console.log('  ...');
  }
});
console.log(`# ${String(cases.length - failed)} passed, ${String(failed)} failed`);
process.exitCode = failed === 0 ? 0 : 1;
